"""Browser end-to-end check of the REAL-PROVIDER UI path. IMPORTANT: Azure is replaced by a LOCAL MOCK (tests/fixtures/run-mock-azure.ts).
This verifies the interface and the real SDK code path; it is NOT a connection to Azure. Run via scripts/e2e-all.sh."""
import sys, re, json, urllib.request
from playwright.sync_api import sync_playwright, expect
BASE = 'http://127.0.0.1:5173'; PW = 'DemoPass#2026'; OUT = '/tmp/shots'; results = []
def mock(behaviour):
    urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:4500/__mock/behaviour', data=json.dumps({'behaviour': behaviour}).encode(), method='POST', headers={'content-type': 'application/json'}))
def check(name, fn):
    try: fn(); results.append((name, True, ''))
    except Exception as e: results.append((name, False, str(e).splitlines()[0][:170]))
def login(page, who):
    page.goto(f'{BASE}/login'); page.fill('#email', f'{who}@demo.neocareai.test'); page.fill('#password', PW); page.click('button:has-text("Sign in")'); page.wait_for_url(BASE + '/')
def open_alert(page):
    page.goto(f'{BASE}/alerts'); page.locator('.alert-row', has_text='NB-0001').first.get_by_role('link', name=re.compile('Review alert|Open')).click(); page.wait_for_selector('text=Why this alert was generated')
with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': 1360, 'height': 1000}); page = ctx.new_page(); login(page, 'doctor'); open_alert(page)
    panel = page.locator('#ai-h').locator('xpath=ancestor::section')
    check('Azure is offered but Demo Mode is the default until chosen', lambda: (expect(panel.get_by_role('radio', name=re.compile('Demo Mode')).first).to_be_checked(), expect(panel.get_by_role('radio', name=re.compile('Azure OpenAI')).first).to_be_enabled()))
    panel.get_by_role('radio', name=re.compile('Azure OpenAI')).check(); panel.get_by_role('button', name='Summarise this alert').click()
    check('real-provider result is labelled as generated by Azure OpenAI, with the model', lambda: expect(page.get_by_text(re.compile('Generated by Azure OpenAI · gpt-4o-mock')).first).to_be_visible())
    check('result does not carry the Demo Mode result label', lambda: expect(page.locator('[aria-live=polite]').get_by_text('Demo Mode – Not Connected to Azure')).to_have_count(0))
    check('factual statements show source record chips', lambda: (expect(page.get_by_text('F1', exact=True).first).to_be_visible(), expect(page.get_by_text('Not known').first).to_be_visible()))
    check('uncertainty and missing information are shown', lambda: expect(page.get_by_text('What the AI did not have')).to_be_visible())
    check('checks panel says passing is not clinical correctness', lambda: (page.get_by_text('Checks, sources and limitations').click(), expect(page.get_by_text('Automated checks passed.')).to_be_visible(), expect(page.get_by_text('does not mean the text is clinically correct', exact=False)).to_be_visible()))
    page.screenshot(path=f'{OUT}/azure_summary.png', full_page=True)

    mock('server_error'); panel.get_by_role('button', name='Summarise this alert').click()
    check('service outage shows a clear error and no substituted text', lambda: (expect(page.get_by_text('The AI service is currently unavailable.')).to_be_visible(), expect(page.get_by_text('Nothing was substituted', exact=False)).to_be_visible(), expect(page.get_by_text(re.compile('Generated by Azure OpenAI')).first).to_have_count(0)))
    page.screenshot(path=f'{OUT}/azure_error.png', full_page=True)
    page.get_by_role('button', name='Switch to Demo Mode and run again').click()
    check('explicit switch to Demo Mode gives a template result labelled as such', lambda: (expect(page.get_by_text('Template text. No AI model was used.', exact=False)).to_be_visible(), expect(page.get_by_role('radio', name=re.compile('Demo Mode')).first).to_be_checked()))

    mock('diagnosis'); panel.get_by_role('radio', name=re.compile('Azure OpenAI')).check(); panel.get_by_role('button', name='Summarise this alert').click()
    check('unsafe model output is rejected and not shown', lambda: (expect(page.get_by_text('did not pass the accuracy and safety checks', exact=False).first).to_be_visible(), expect(page.get_by_text('sepsis', exact=False)).to_have_count(0)))
    mock('bad_number'); panel.get_by_role('button', name='Summarise this alert').click()
    check('unsupported number is rejected with the failed check named', lambda: expect(page.get_by_text('numbers_grounded', exact=False).first).to_be_visible())
    mock('ok')

    panel.get_by_role('button', name='Prepare draft assessment').click(); page.wait_for_selector('pre')
    check('draft shows AI provenance and clinician-only fields', lambda: (expect(page.locator('pre')).to_contain_text('Prepared by an AI model'), expect(page.locator('pre')).to_contain_text('[Clinician to complete')))
    page.get_by_role('button', name='Reject draft').click()
    check('rejecting a draft is explicit and removes the option to use it', lambda: (expect(page.get_by_text('Draft rejected.')).to_be_visible(), expect(page.get_by_role('button', name='Edit draft in assessment form')).to_have_count(0)))
    page.get_by_role('button', name='Acknowledge alert').click(); page.wait_for_timeout(900)
    panel.get_by_role('button', name='Prepare draft assessment').click(); page.wait_for_selector('pre'); page.get_by_role('button', name='Edit draft in assessment form').click()
    dlg = page.get_by_role('dialog')
    check('draft dialog names Azure as the source and blocks recording while incomplete', lambda: (expect(dlg.get_by_text('Started from an AI-generated draft (Azure OpenAI).')).to_be_visible(), expect(dlg.get_by_role('button', name='Record assessment')).to_be_disabled()))
    ta = dlg.locator('textarea').first; ta.fill(re.sub(r'\[Clinician to complete[^\]]*\]', 'Completed by the clinician (synthetic demo).', ta.input_value()))
    dlg.get_by_role('button', name='Record assessment').click(); page.wait_for_timeout(1200)
    check('history records that an Azure-generated draft was used and edited by the clinician', lambda: expect(page.get_by_text(re.compile('generated by Azure OpenAI.*Edited and recorded by the clinician'))).to_be_visible())
    page.screenshot(path=f'{OUT}/azure_after.png', full_page=True)

    actx = b.new_context(viewport={'width': 1360, 'height': 1000}); apg = actx.new_page(); login(apg, 'admin'); apg.goto(f'{BASE}/settings'); apg.get_by_role('tab', name='AI assistance').click(); apg.wait_for_timeout(900)
    check('administrator sees Azure configured but unverified until tested', lambda: (expect(apg.get_by_text('Azure configured', exact=True)).to_be_visible(), expect(apg.get_by_text('has not been verified against Azure', exact=False)).to_be_visible()))
    apg.get_by_role('button', name='Test Azure connection').click()
    check('connection test result is shown and recorded', lambda: (expect(apg.get_by_text('Connected. The model answered', exact=False)).to_be_visible(), expect(apg.get_by_text('Last test:', exact=False)).to_be_visible()))
    check('activity table shows source, model, outcomes and clinician decisions', lambda: (expect(apg.locator('td', has_text='Azure OpenAI').first).to_be_visible(), expect(apg.get_by_text('Rejected', exact=True).first).to_be_visible(), expect(apg.get_by_text('Recorded (edited)').first).to_be_visible(), expect(apg.get_by_text('failed', exact=False).first).to_be_visible()))
    apg.screenshot(path=f'{OUT}/azure_admin.png', full_page=True)
    ctx2 = b.new_context(); np_ = ctx2.new_page(); login(np_, 'nurse'); open_alert(np_)
    check('nurse sees summary and checklist but no draft button', lambda: (expect(np_.get_by_role('button', name='Documentation checklist')).to_be_visible(), expect(np_.get_by_role('button', name='Prepare draft assessment')).to_have_count(0)))
    b.close()
ok = sum(r[1] for r in results)
for n, s, m in results: print(('PASS ' if s else 'FAIL ') + n + (f'  -> {m}' if m else ''))
print(f'{ok}/{len(results)} passed'); sys.exit(0 if ok == len(results) else 1)
